@'
using UnityEngine;using UnityEngine.UI;
public class RuntimeUIApiCounter:MonoBehaviour {public int Hits;public int Order;public int OffHits;public int Awakes;public int Enables;public int Starts;public int Disables;public GameObject Button;public Canvas CanvasComponent;public Button ActionComponent;public bool SameCanvas;public bool SameButton;public bool SeenCanvas;public bool SeenEnabled;public bool SeenInteractable;void Update(){var panel=gameObject.GetComponent<Canvas>();var action=Button.GetComponent<Button>();SameCanvas=panel==CanvasComponent;SameButton=action==ActionComponent;SeenCanvas=panel.enabled;SeenEnabled=action.enabled;SeenInteractable=action.interactable;}void Awake(){Awakes++;}void OnEnable(){Enables++;}void Start(){Starts++;}void OnDisable(){Disables++;}public void First(){Hits++;Order=1;}public void Second(){Order=Order*10+2;}public void Off(){OffHits++;}}
'@|Set-Content ($folder+'/RuntimeUIApiCounter.cs')
