@'
using UnityEngine;using UnityEngine.UI;using UnityEngine.SceneManagement;
public class RuntimeUIApiDriver:MonoBehaviour {
 public int Frame;public GameObject Source;public GameObject Dormant;public GameObject Disabled;public GameObject Quiet;public GameObject First;public GameObject Second;public GameObject Copy;public GameObject Sleeping;public GameObject Hidden;public GameObject Passive;public RuntimeUIApiCounter A;public RuntimeUIApiCounter B;public RuntimeUIApiCounter C;public RuntimeUIApiCounter D;public RuntimeUIApiCounter E;public RuntimeUIApiCounter F;public GameObject Scene;public GameObject SceneCopy;public RuntimeUIApiCounter SceneCounter;public RuntimeUIApiCounter SceneCopyCounter;public RuntimeUIApiExternal Outside;
 void Update(){Frame++;if(Frame==2){First=Instantiate(Source);A=First.GetComponent<RuntimeUIApiCounter>();}if(Frame==3){A.CanvasComponent.enabled=false;}if(Frame==4){A.CanvasComponent.enabled=true;Second=Instantiate(Source);B=Second.GetComponent<RuntimeUIApiCounter>();}if(Frame==5){A.ActionComponent.interactable=false;}if(Frame==6){A.ActionComponent.interactable=true;Copy=Instantiate(First);C=Copy.GetComponent<RuntimeUIApiCounter>();}if(Frame==7){A.ActionComponent.enabled=false;}if(Frame==8){A.ActionComponent.enabled=true;Sleeping=Instantiate(Dormant);D=Sleeping.GetComponent<RuntimeUIApiCounter>();}if(Frame==9){Sleeping.SetActive(true);}if(Frame==10){First.SetActive(false);SceneCopy=Instantiate(Scene);SceneCopyCounter=SceneCopy.GetComponent<RuntimeUIApiCounter>();}if(Frame==11){SceneCounter.ActionComponent.interactable=false;}if(Frame==12){First.SetActive(true);SceneCounter.ActionComponent.interactable=true;}if(Frame==13){B.Button.SetActive(false);}if(Frame==14){B.Button.SetActive(true);}if(Frame==15){Hidden=Instantiate(Disabled);E=Hidden.GetComponent<RuntimeUIApiCounter>();}if(Frame==16){E.CanvasComponent.enabled=true;Passive=Instantiate(Quiet);F=Passive.GetComponent<RuntimeUIApiCounter>();}if(Frame==17){Destroy(First);}if(Frame==18){Destroy(Scene);}if(Frame==20){Destroy(SceneCopy);Destroy(Second);Destroy(Copy);Destroy(Passive);}if(Frame==22){SceneManager.LoadScene(1);}}
}
'@|Set-Content ($folder+'/RuntimeUIApiDriver.cs')
@'
using UnityEngine;using UnityEngine.UI;using UnityEngine.Events;using UnityEditor;using UnityEditor.Events;using UnityEditor.SceneManagement;
public static class EMPrepareUIApi {
 static GameObject Make(string name,bool active,bool enabled){var root=new GameObject(name,typeof(RectTransform),typeof(Canvas),typeof(CanvasScaler),typeof(GraphicRaycaster));root.GetComponent<Canvas>().renderMode=RenderMode.ScreenSpaceOverlay;root.GetComponent<Canvas>().enabled=enabled;var count=root.AddComponent<RuntimeUIApiCounter>();var button=new GameObject("Action",typeof(RectTransform),typeof(Image),typeof(Button));button.transform.SetParent(root.transform,false);var rect=(RectTransform)button.transform;rect.anchorMin=rect.anchorMax=rect.pivot=new Vector2(.5f,.5f);rect.anchoredPosition=new Vector2(40,-30);rect.sizeDelta=new Vector2(180,60);button.GetComponent<Image>().color=new Color(.8f,.3f,.15f,1);var child=button.AddComponent<RuntimeUIApiChild>();count.Button=button;count.CanvasComponent=root.GetComponent<Canvas>();count.ActionComponent=button.GetComponent<Button>();button.GetComponent<Button>().transition=Selectable.Transition.None;var click=button.GetComponent<Button>().onClick;UnityEventTools.AddVoidPersistentListener(click,count.First);UnityEventTools.AddVoidPersistentListener(click,child.Hit);UnityEventTools.AddVoidPersistentListener(click,count.Second);UnityEventTools.AddVoidPersistentListener(click,count.Off);click.SetPersistentListenerState(3,UnityEventCallState.Off);if(name=="UIPassive")while(click.GetPersistentEventCount()>0)UnityEventTools.RemovePersistentListener(click,0);var label=new GameObject("Label",typeof(RectTransform),typeof(Text));label.transform.SetParent(button.transform,false);var text=label.GetComponent<Text>();text.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");text.text="PORT";text.supportRichText=false;text.fontSize=20;text.alignment=TextAnchor.MiddleCenter;text.raycastTarget=false;root.SetActive(active);root.transform.localScale=Vector3.one;var asset=PrefabUtility.SaveAsPrefabAsset(root,"Assets/RuntimeUIApi/"+name+".prefab");Object.DestroyImmediate(root);return asset;}
 public static void Run(){var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var driver=new GameObject("UI Prefab Driver").AddComponent<RuntimeUIApiDriver>();driver.Source=Make("UIActive",true,true);driver.Dormant=Make("UIDormant",false,true);driver.Disabled=Make("UIDisabled",true,false);driver.Quiet=Make("UIPassive",true,true);var sceneUI=(GameObject)PrefabUtility.InstantiatePrefab(driver.Source);PrefabUtility.UnpackPrefabInstance(sceneUI,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);sceneUI.name="UIScene";driver.Scene=sceneUI;driver.SceneCounter=sceneUI.GetComponent<RuntimeUIApiCounter>();driver.Outside=new GameObject("UI External Target").AddComponent<RuntimeUIApiExternal>();UnityEventTools.AddVoidPersistentListener(driver.SceneCounter.ActionComponent.onClick,driver.Outside.Hit);MonoImporter.SetExecutionOrder(MonoScript.FromMonoBehaviour(driver),-1000);EditorSceneManager.SaveScene(scene,"Assets/RuntimeUIApi/UIApi.unity");EditorBuildSettings.scenes=new[]{new EditorBuildSettingsScene("Assets/RuntimeUIApi/UIApi.unity",true),new EditorBuildSettingsScene("Assets/RuntimeWorld/RuntimeMiddle.unity",true),new EditorBuildSettingsScene("Assets/RuntimeWorld/RuntimeFinal.unity",true)};AssetDatabase.SaveAssets();Debug.Log("RUNTIME_UI_API_FIXTURE_READY");}
}
